import {AnalyticsProvider} from '@github-ui/analytics-provider'
import {PartialEntry} from '@github-ui/react-core/partial-entry'
import {PartialRouter} from '@github-ui/react-core/partial-router'
import {Route, Routes} from '@github-ui/react-router'
import {RelayEnvironmentProvider, relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'
import {useNavigate} from '@github-ui/use-navigate'
import {type Key, useEffect, useMemo, useState} from 'react'
import type {Root} from 'react-dom/client'

import {VALUES} from '../constants/values'
import {getSafeConfig} from '../utils/option-config'
import {CreateIssueDialogEntry} from './CreateIssueDialogEntry'

export function renderCreateDialogPartialEntry(root: Root, {key, ...props}: CreateIssueModalProps & {key: Key}) {
  const routeContent = (
    <Routes>
      <Route path="*" element={<WrapperComponent {...props} />} />
    </Routes>
  )

  root.render(
    <PartialEntry key={key} partialName="issue-create">
      <PartialRouter partialName="issue-create">{routeContent}</PartialRouter>
    </PartialEntry>,
  )
}

const environment = relayEnvironmentWithMissingFieldHandlerForNode()

function WrapperComponent({analyticsAppName, analyticsNamespace, owner, repository}: CreateIssueModalProps) {
  return (
    <RelayEnvironmentProvider environment={environment}>
      <AnalyticsProvider
        appName={analyticsAppName ?? 'UNKNOWN'}
        category={analyticsNamespace ?? 'issue-create-web-component'}
        metadata={{}}
      >
        <CreateIssueModal owner={owner} repository={repository} />
      </AnalyticsProvider>
    </RelayEnvironmentProvider>
  )
}

export type CreateIssueModalProps = {
  owner?: string
  repository?: string
  analyticsAppName?: string
  analyticsNamespace?: string
}

export function CreateIssueModal({owner, repository}: CreateIssueModalProps) {
  const [isVisible, setIsVisible] = useState(true)
  const navigate = useNavigate()

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setIsVisible(true)
  }, [])

  const repo = useMemo(
    () =>
      owner && repository
        ? {
            repository: {
              owner,
              name: repository,
            },
          }
        : undefined,
    [owner, repository],
  )

  if (!isVisible) return null

  return (
    <CreateIssueDialogEntry
      navigate={navigate} // Added to allow redirect to UserRestrictedView from the global AppBar
      isCreateDialogOpen={isVisible}
      setIsCreateDialogOpen={setIsVisible}
      optionConfig={getSafeConfig({
        storageKeyPrefix: VALUES.storageKeyPrefixes.globalAdd,
        issueCreateArguments: repo,
        showFullScreenButton: false,
      })}
    />
  )
}
